module Top;
    localparam logic [1:0] READ = 2'd1;
    logic [1:0] cur_state;
    logic wvalid, wready;
    logic [15:0] wstrb;
    logic cen;
    logic [15:0] wen;
    logic [3:0] st = 4'd2;
    logic hit;
    always @(cur_state or wvalid or wready or wstrb[15:0]) begin
        if (cur_state == READ) begin
            cen = 1'b0;
            wen = 16'hffff;
        end else if (wvalid && wready) begin
            cen = 1'b0;
            wen = ~wstrb;
        end else begin
            cen = 1'b1;
            wen = 16'hffff;
        end
    end
    always @* hit = (st == 4'd2);
    initial begin
        #1 $display("%b %h %b", cen, wen, hit);
        $finish;
    end
endmodule

module Top;
    logic [3:0] a, b;
    logic [3:0] y, z;
    always @(a or b) y = a + 4'd1;
    always @(a) z = a + b + 4'd2;
    initial begin
        b = 4'd5;
        #1 $display("%0d %0d", y, z);
        $finish;
    end
endmodule
